def _feasible(pts, tol=0.0):
    x = pts[:, 0]; y = pts[:, 1]; r = pts[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
        return False
    if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
        return False
    dx = x[:, None] - x[None, :]
    dy = y[:, None] - y[None, :]
    d2 = dx * dx + dy * dy
    rs = r[:, None] + r[None, :]
    np.fill_diagonal(d2, np.inf)
    if np.any(d2 < rs * rs - 1e-12):
        return False
    return True


def _score(pts):
    return pts[:, 2].sum()


def _hex_grid(n=32):
    pts = []
    k = 6
    dy = 1.0 / k
    dx = 1.0 / k
    for j in range(k + 1):
        off = 0.5 * dx if (j % 2) else 0.0
        for i in range(k + 1):
            if len(pts) < n:
                x = (i + 0.5) * dx + off
                y = (j + 0.5) * dy
                if x < 1 and y < 1:
                    pts.append([x, y, 0.4 / k])
    while len(pts) < n:
        pts.append([0.5, 0.5, 0.1])
    return np.array(pts[:n], dtype=float)


def _perturb(pts, rng, mode):
    p = pts.copy()
    n = len(p)
    if mode == 0:
        s = 0.0005 + 0.002 * rng.random()
        p[:, 0] += rng.normal(0, s, n); p[:, 1] += rng.normal(0, s, n)
    elif mode == 1:
        a = rng.integers(n)
        p[a, 0] += rng.normal(0, 0.02); p[a, 1] += rng.normal(0, 0.02)
    elif mode == 2:
        a, b = rng.choice(n, 2, replace=False)
        p[[a, b], 0] = p[[b, a], 0]; p[[a, b], 1] = p[[b, a], 1]
        p[:, 0] += rng.normal(0, 0.002, n); p[:, 1] += rng.normal(0, 0.002, n)
    elif mode == 3:
        p[:, 0] += rng.normal(0, 0.006, n); p[:, 1] += rng.normal(0, 0.006, n)
        p[:, 2] *= (1 + rng.normal(0, 0.004, n))
    elif mode == 4:
        p[:, 0] += rng.normal(0, 0.02, n); p[:, 1] += rng.normal(0, 0.02, n)
    else:
        a = rng.integers(n)
        p[a, 0] = rng.random(); p[a, 1] = rng.random()
        p[:, 0] += rng.normal(0, 0.004, n); p[:, 1] += rng.normal(0, 0.004, n)
    p[:, 0] = np.clip(p[:, 0], 1e-3, 1 - 1e-3)
    p[:, 1] = np.clip(p[:, 1], 1e-3, 1 - 1e-3)
    p[:, 2] = np.maximum(p[:, 2], 1e-4)
