        pts.append([0.5, 0.5, 0.1])
    return np.array(pts[:n], dtype=float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    n = 32
    rng = np.random.default_rng(1234567)

    if start is not None and np.asarray(start).shape == (32, 3):
        best = np.array(start, dtype=float)
    else:
        best = _hex_grid(n)

    iu, ju = np.triu_indices(n, k=1)
    n_pairs = len(iu)

    def unpack(z):
        return z[:n], z[n:2 * n], z[2 * n:]

    def con_walls(z):
        x, y, r = unpack(z)
        return np.concatenate([x - r, 1 - x - r, y - r, 1 - y - r])

    def con_pairs(z):
        x, y, r = unpack(z)
        dx = x[iu] - x[ju]; dy = y[iu] - y[ju]
        rs = r[iu] + r[ju]
        return dx * dx + dy * dy - rs * rs

    constraints = [
        {'type': 'ineq', 'fun': con_walls},
        {'type': 'ineq', 'fun': con_pairs},
    ]

    def objective(z):
        return -np.sum(z[2 * n:])

    def pack(z0, maxiter=300):
        bounds = [(0.0, 1.0)] * (2 * n) + [(1e-8, 0.5)] * n
        try:
            res = minimize(objective, z0, method='SLSQP',
                           bounds=bounds, constraints=constraints,
                           options={'maxiter': maxiter, 'ftol': 1e-14})
            return res.x
        except Exception:
            return z0

    def to_z(p):
        return np.concatenate([p[:, 0], p[:, 1], p[:, 2]])

    def to_pts(z):
        return np.column_stack([z[:n], z[n:2 * n], z[2 * n:]])

    def score_of(p):
        return p[:, 2].sum()

    def feasible(p, tol=1e-10):
        x = p[:, 0]; y = p[:, 1]; r = p[:, 2]
        if np.any(r <= 0):
            return False
        if np.any(x - r < -tol) or np.any(x + r > 1 + tol):
            return False
        if np.any(y - r < -tol) or np.any(y + r > 1 + tol):
            return False
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        d2 = dx * dx + dy * dy
        rs = r[:, None] + r[None, :]
        np.fill_diagonal(d2, np.inf)
        return not np.any(d2 < rs * rs - tol)

    def lp_radii(pts):
        """Given centers, solve LP to maximize sum r s.t. wall & pair constraints."""
        x = pts[:, 0]; y = pts[:, 1]
        wall_cap = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
        wall_cap = np.maximum(wall_cap, 0.0)
        d = np.sqrt((x[:, None] - x[None, :]) ** 2 + (y[:, None] - y[None, :]) ** 2)
        c = -np.ones(n)
        A = []
        b = []
        for i in range(n):
            row = np.zeros(n); row[i] = 1.0
            A.append(row); b.append(wall_cap[i])
        for a in range(n):
            for bb in range(a + 1, n):
                row = np.zeros(n); row[a] = 1.0; row[bb] = 1.0
                A.append(row); b.append(d[a, bb])
        try:
            res = linprog(c, A_ub=np.array(A), b_ub=np.array(b),
                          bounds=[(0, None)] * n, method='highs')
            if res.success:
                return np.maximum(res.x, 1e-9)
        except Exception:
            pass
        return pts[:, 2].copy()

