        for _ in range(2000):
            if feasible(best, tol=1e-9):
                break
            best[:, 2] *= 0.999
    z = pack(to_z(best), maxiter=800)
    cand = to_pts(z)
    if feasible(cand, tol=1e-9) and score_of(cand) > score_of(best):
        best = cand
    best_score = score_of(best)

    # Main loop: LP radii on perturbed centers, then SLSQP
    attempts = 0
    while time.process_time() < deadline:
        attempts += 1
        cand_pts = best.copy()
        mode = attempts % 6
        if mode == 0:
            # small jitter on centers
            cand_pts[:, 0] += rng.normal(0, 0.004, n)
            cand_pts[:, 1] += rng.normal(0, 0.004, n)
        elif mode == 1:
            # larger jitter
            cand_pts[:, 0] += rng.normal(0, 0.015, n)
            cand_pts[:, 1] += rng.normal(0, 0.015, n)
        elif mode == 2:
            # swap two centers
            a, b = rng.choice(n, 2, replace=False)
            cand_pts[[a, b], :2] = cand_pts[[b, a], :2]
            cand_pts[:, 0] += rng.normal(0, 0.005, n)
            cand_pts[:, 1] += rng.normal(0, 0.005, n)
        elif mode == 3:
            # move one circle
            a = rng.integers(n)
            cand_pts[a, 0] += rng.normal(0, 0.02)
            cand_pts[a, 1] += rng.normal(0, 0.02)
        elif mode == 4:
            # rotate subset
            idx = rng.choice(n, size=max(3, n // 3), replace=False)
            cx, cy = cand_pts[idx, 0].mean(), cand_pts[idx, 1].mean()
            th = rng.normal(0, 0.08)
            c, s = np.cos(th), np.sin(th)
            dx = cand_pts[idx, 0] - cx; dy = cand_pts[idx, 1] - cy
            cand_pts[idx, 0] = cx + c * dx - s * dy
            cand_pts[idx, 1] = cy + s * dx + c * dy
        else:
            cand_pts[:, 0] += rng.normal(0, 0.008, n)
            cand_pts[:, 1] += rng.normal(0, 0.008, n)

        cand_pts[:, 0] = np.clip(cand_pts[:, 0], 1e-4, 1 - 1e-4)
        cand_pts[:, 1] = np.clip(cand_pts[:, 1], 1e-4, 1 - 1e-4)

        # Recompute radii via LP for new centers (this is the key change)
        cand_pts[:, 2] = lp_radii(cand_pts)

        if not feasible(cand_pts, tol=1e-9):
            for _ in range(200):
                cand_pts[:, 2] *= 0.995
                if feasible(cand_pts, tol=1e-9):
                    break

        z = pack(to_z(cand_pts), maxiter=250)
        cand = to_pts(z)
        if feasible(cand, tol=1e-9):
            s = score_of(cand)
            if s > best_score + 1e-12:
                best = cand
                best_score = s

    # Final polish
    if time.process_time() < deadline + budget_seconds * 0.05:
        # LP radii on best centers, then SLSQP
        best[:, 2] = lp_radii(best)
        if not feasible(best, tol=1e-9):
            for _ in range(500):
                best[:, 2] *= 0.998
                if feasible(best, tol=1e-9):
                    break
        z = pack(to_z(best), maxiter=2000)
        cand = to_pts(z)
        if feasible(cand, tol=1e-9) and score_of(cand) > best_score:
            best = cand
            best_score = score_of(cand)

    # Final exact-feasibility shrink
    best = best.copy()
    best[:, 2] = np.maximum(best[:, 2], 1e-9)
    for _ in range(20000):
        x = best[:, 0]; y = best[:, 1]; r = best[:, 2]
        ok = np.all(r > 0)
        ok = ok and np.all(x - r >= 0) and np.all(x + r <= 1)
        ok = ok and np.all(y - r >= 0) and np.all(y + r <= 1)
        if ok:
            dx = x[:, None] - x[None, :]
            dy = y[:, None] - y[None, :]
            d2 = dx * dx + dy * dy
            rs = r[:, None] + r[None, :]
            np.fill_diagonal(d2, np.inf)
            ok = not np.any(d2 < rs * rs)
        if ok:
            break
        best[:, 2] *= (1 - 1e-11)
    return best

