                          bounds=[(0, None)] * n, method='highs')
            if res.success:
                return np.maximum(res.x, 0.0)
        except Exception:
            pass
        return pts[:, 2].copy()

    z_best = pack(to_z(best), maxiter=1000)
    cand = to_pts(z_best)
    if feasible_soft(cand) and score_of(cand) > score_of(best):
        best = cand
    best_score = score_of(best)

    attempt = 0
    last_improve = 0
    while time.process_time() < deadline:
        attempt += 1
        cand_pts = best.copy()
        mode = attempt % 8
        if mode == 0:
            cand_pts[:, 0] += rng.normal(0, 0.002, n)
            cand_pts[:, 1] += rng.normal(0, 0.002, n)
            cand_pts[:, 2] *= (1 + rng.normal(0, 0.003, n))
        elif mode == 1:
            a = rng.integers(n)
            cand_pts[a, 0] += rng.normal(0, 0.01)
            cand_pts[a, 1] += rng.normal(0, 0.01)
        elif mode == 2:
            a, b = rng.choice(n, 2, replace=False)
            cand_pts[[a, b], :2] = cand_pts[[b, a], :2]
            cand_pts[:, 0] += rng.normal(0, 0.003, n)
            cand_pts[:, 1] += rng.normal(0, 0.003, n)
        elif mode == 3:
            cand_pts[:, 2] *= (1 + rng.normal(0, 0.006, n))
        elif mode == 4:
            cand_pts[:, 0] += rng.normal(0, 0.008, n)
            cand_pts[:, 1] += rng.normal(0, 0.008, n)
            cand_pts[:, 2] *= (1 + rng.normal(0, 0.005, n))
        elif mode == 5:
            cand_pts[:, 0] += rng.normal(0, 0.02, n)
            cand_pts[:, 1] += rng.normal(0, 0.02, n)
        elif mode == 6:
            newr = max_radii_lp(cand_pts)
            cand_pts[:, 2] = 0.995 * newr
        else:
            idx = rng.choice(n, size=max(2, n // 4), replace=False)
            cx, cy = cand_pts[idx, 0].mean(), cand_pts[idx, 1].mean()
            th = rng.normal(0, 0.05)
            c, s = np.cos(th), np.sin(th)
            dx = cand_pts[idx, 0] - cx; dy = cand_pts[idx, 1] - cy
            cand_pts[idx, 0] = cx + c * dx - s * dy
            cand_pts[idx, 1] = cy + s * dx + c * dy

        cand_pts[:, 0] = np.clip(cand_pts[:, 0], 1e-3, 1 - 1e-3)
        cand_pts[:, 1] = np.clip(cand_pts[:, 1], 1e-3, 1 - 1e-3)
        cand_pts[:, 2] = np.maximum(cand_pts[:, 2], 1e-4)

        if not feasible_soft(cand_pts):
            for _ in range(120):
                cand_pts[:, 2] *= 0.995
                if feasible_soft(cand_pts):
                    break

        z = pack(to_z(cand_pts), maxiter=300)
        cand = to_pts(z)
        if feasible_soft(cand):
            s = score_of(cand)
            if s > best_score + 1e-13:
                best = cand
                best_score = s
                last_improve = attempt

        if attempt - last_improve > 50 and time.process_time() < deadline:
            hg = _hex_grid(n)
            hg[:, 0] += rng.normal(0, 0.02, n)
            hg[:, 1] += rng.normal(0, 0.02, n)
            hg[:, 0] = np.clip(hg[:, 0], 0.02, 0.98)
            hg[:, 1] = np.clip(hg[:, 1], 0.02, 0.98)
            for _ in range(80):
                if feasible_soft(hg):
                    break
                hg[:, 2] *= 0.99
            z = pack(to_z(hg), maxiter=400)
            cand = to_pts(z)
            if feasible_soft(cand) and score_of(cand) > best_score:
                best = cand
                best_score = score_of(cand)
                last_improve = attempt

    if time.process_time() < deadline + budget_seconds * 0.05:
        z = pack(to_z(best), maxiter=1500)
        cand = to_pts(z)
        if feasible_soft(cand) and score_of(cand) > best_score:
            best = cand
            best_score = score_of(cand)

    best = best.copy()
    best[:, 2] = np.maximum(best[:, 2], 1e-9)
    for _ in range(10000):
        x = best[:, 0]; y = best[:, 1]; r = best[:, 2]
        ok = np.all(r > 0)
        ok = ok and np.all(x - r >= 0) and np.all(x + r <= 1)
        ok = ok and np.all(y - r >= 0) and np.all(y + r <= 1)
        if ok:
            dx = x[:, None] - x[None, :]
            dy = y[:, None] - y[None, :]
            d2 = dx * dx + dy * dy
            rs = r[:, None] + r[None, :]
            np.fill_diagonal(d2, np.inf)
            ok = not np.any(d2 < rs * rs)
        if ok:
            break
        best[:, 2] *= (1 - 1e-12)
    return best
